"""Generate crawlable GitHub Pages from public Apple metadata and editorial copy."""
from pathlib import Path
import json, html, re
ROOT=Path(__file__).resolve().parents[1]
BASE='https://skylight777.github.io/ihor-apps/'
apps=json.loads((ROOT/'data/apps.json').read_text())
# id: slug, short name, collection, headline, summary, accent, use case
copy={
6792562428:('dayline','DayLine','Everyday','A little today.\nA lifetime tomorrow.','One line a day. The same date, year after year. A private journal for the moments you want to keep.','#ebe3d3','Keep a one-line journal without a subscription'),
6792862460:('routine-timer','Routine Timer','Everyday','Big timers.\nSmall steps.','Turn mornings, homework and bedtime into visual steps. One clear timer at a time.','#e4eafb','Build a visual morning routine for kids'),
6800721865:('reading-log-xl','Reading Log XL','Everyday','One more page.\nOne lasting habit.','Keep your books, reading minutes and progress together. Make a one-page report for school.','#e8e4d9','Track reading minutes and make a school reading report'),
6809777790:('printexact','PrintExact','Creative','Your photo.\nExactly your size.','Print photos, craft templates and posters at the dimensions you choose. Millimetres, centimetres or inches.','#e0e9f1','Print a photo at an exact size from iPhone'),
6817095103:('lucida-cam','Lucida Cam','Creative','Your reference.\nYour pencil.','See your reference over the live camera view. Look at the screen, and draw on real paper.','#eee6dc','Trace a photo onto paper using an iPhone camera'),
6792683658:('bp-log-xl','BP Log XL','Health','Your readings.\nClearly kept.','A blood pressure journal with large numbers. Record systolic, diastolic and pulse, then share your history.','#e0eaf4','Keep a large-print blood pressure log for a doctor'),
6793054896:('sugar-log-xl','Sugar Log XL','Health','Less squinting.\nClearer records.','Log blood sugar in large, readable numbers. Tag readings around meals and keep a history for your doctor.','#e2eaf2','Keep a manual blood sugar diary in mg/dL or mmol/L'),
6796485536:('cholesterol-log-xl','Cholesterol Log XL','Health','Every panel.\nOne clear picture.','Keep Total, LDL, HDL and Triglycerides together. Large print, your units, and a report to share.','#e2e9ef','Keep cholesterol lab results in a large-print journal'),
6796485894:('meno-log','Meno Log','Health','Every moment.\nA clearer pattern.','Record each hot flash when it happens. Keep symptoms, intensity and day-and-night history in one private log.','#f3e3df','Track individual hot flashes and export a symptom log'),
6808273868:('glp-1-log','GLP-1 Log','Health','Shot day.\nAll in one place.','Keep a record of medicines, doses, injection sites, weight and side effects. See when your next shot is due.','#e0eae6','Log GLP-1 injections and keep track of injection sites'),
6796486042:('expense-log-xl','Expense Log XL','Money','Know where\nit goes.','Enter an amount. Pick a category. Keep a clear monthly spending record without connecting your bank.','#e3e9e3','Track expenses manually without linking a bank account'),
6801566178:('bill-reminder-xl','Bill Reminder XL','Money','Keep the dates.\nSkip the scramble.','Enter a bill once. Get reminders, mark it paid, and let the next due date take its place.','#e4e8f5','Organize recurring bills and due-date reminders'),
6801566475:('debt-payoff-xl','Debt Payoff XL','Money','A plan for\nthe last payment.','Compare debt snowball and avalanche plans using your balances, rates and payments. See the path month by month.','#e1e8f1','Compare debt snowball and avalanche payoff plans offline'),
6800723335:('pocket-money','Pocket Money','Money','Little lessons.\nGrowing goals.','Keep track of cash allowance, chores and savings goals for your kids. No bank cards or accounts to connect.','#e4ecdf','Track children’s cash allowance and chores without a bank card')}
byid={a['trackId']:a for a in apps}
order=[6792562428,6817095103,6809777790,6792862460,6800721865,6792683658,6793054896,6796485536,6796485894,6808273868,6796486042,6801566178,6801566475,6800723335]
esc=lambda s:html.escape(str(s),quote=True)
def meta(a):return copy[a['trackId']]
def shot(a,n=1,prefix=''):
 return f'{prefix}assets/{a["trackId"]}/screen-{n}.jpg'
def icon(a,prefix=''):return f'{prefix}assets/{a["trackId"]}/icon.png'
def store(a):return f'https://apps.apple.com/app/id{a["trackId"]}'
def head(title,desc,path='',prefix='',schema=None,img=None):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(desc)}"><meta name="theme-color" content="#f5f5f7"><link rel="canonical" href="{BASE+path}"><meta property="og:type" content="website"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(desc)}"><meta property="og:url" content="{BASE+path}"><meta property="og:image" content="{BASE+(img or 'assets/6792562428/icon.png')}"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="{prefix}favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}style.css"><script src="{prefix}site.js" defer></script>{'<script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False)+'</script>' if schema else ''}</head><body><a class="skip" href="#main">Skip to content</a>'''
def nav(prefix=''):
 return f'''<header class="site-nav"><nav aria-label="Main navigation"><a class="wordmark" href="{prefix or './'}" aria-label="Ihor Romanenko home"><span class="monogram">ir</span><span>Ihor Romanenko</span></a><div class="nav-links"><a href="{prefix}#apps">The apps</a><a href="{prefix}#approach">The approach</a><a href="{prefix}#questions">FAQ</a></div><a class="nav-store" href="https://apps.apple.com/us/developer/ihor-romanenko/id6792562550">App Store <span aria-hidden="true">↗</span></a></nav></header>'''
def footer(prefix=''):
 return f'''<footer><div class="footer-top"><a class="wordmark" href="{prefix or './'}"><span class="monogram">ir</span>Ihor Romanenko</a><p>Small apps. Thoughtfully made.</p></div><div class="footer-bottom"><span>© 2026 Ihor Romanenko</span><a href="{prefix}#apps">All apps</a><a href="https://apps.apple.com/us/developer/ihor-romanenko/id6792562550">Developer on the App Store ↗</a><a href="https://skylight777.github.io/igor-apps-legal/">App policies & support ↗</a></div><p class="fineprint">App availability and prices vary by country. See each App Store listing for current details. Apple and iPhone are trademarks of Apple Inc.</p></footer></body></html>'''
def card(a):
 slug,name,cat,title,desc,color,use=meta(a)
 return f'''<article class="app-card" data-category="{cat}"><div class="card-copy"><img class="app-icon" src="{icon(a)}" alt="" width="56" height="56" loading="lazy"><p class="eyebrow">{cat}</p><h3><a href="{slug}/">{name}</a></h3><p>{desc}</p><a class="text-link" href="{slug}/" aria-label="Explore {name}">Explore the app <span aria-hidden="true">↗</span></a></div><a class="card-visual" style="--tint:{color}" href="{slug}/" aria-label="See {name}"><img src="{shot(a)}" alt="{esc(name)} App Store screenshot" loading="lazy" width="222" height="480"></a></article>'''
# Homepage
home_schema={'@context':'https://schema.org','@type':'CollectionPage','name':'iPhone apps by Ihor Romanenko','url':BASE,'description':'Private iPhone apps for everyday life, creativity, health journals and money tracking.','mainEntity':{'@type':'ItemList','itemListElement':[{'@type':'ListItem','position':i+1,'name':meta(byid[id])[1],'url':BASE+meta(byid[id])[0]+'/'} for i,id in enumerate(order)]}}
out=head('Ihor Romanenko — Thoughtful iPhone Apps','Explore 14 private iPhone apps for journaling, creativity, health records and money. No subscriptions. Find the app for your everyday.',schema=home_schema)+nav()
out+='''<main id="main"><section class="hero"><p class="eyebrow">INDEPENDENT APPS FOR IPHONE</p><h1>Life has its little things.<br><span>There’s an app for yours.</span></h1><p class="hero-description">A line about your day. A picture on paper. A number worth keeping.<br>Simple, private apps by Ihor Romanenko.</p><a class="button" href="#apps">Find your app <span aria-hidden="true">↓</span></a><div class="hero-gallery" aria-label="A look at the apps">'''
for i,id in enumerate([6792683658,6809777790,6792562428,6817095103,6800723335]):
 a=byid[id];out+=f'<a class="hero-screen screen-{i}" href="{meta(a)[0]}/" aria-label="Explore {meta(a)[1]}"><img src="{shot(a)}" alt="{meta(a)[1]} screenshot" width="222" height="480" fetchpriority="{"high" if i==2 else "auto"}"></a>'
out+='''</div><div class="hero-principles"><span>No subscriptions.</span><span>No accounts.</span><span>Your data stays yours.</span></div></section><section class="catalog section-wrap" id="apps"><div class="section-heading"><div><p class="eyebrow">THE COLLECTION</p><h2>Find your everyday.</h2></div><p>One useful thing. <br>Done with care.</p></div><div class="filters" role="group" aria-label="Filter apps by collection">'''
for label in ['All apps','Everyday','Creative','Health','Money']:out+=f'<button type="button" data-filter="{label}" aria-pressed="{"true" if label=="All apps" else "false"}">{label}</button>'
out+='</div><p class="sr-only" id="filter-status" aria-live="polite">Showing 14 apps</p><div class="app-grid">'+''.join(card(byid[id]) for id in order)+'</div></section>'
out+='''<section class="approach" id="approach"><div class="section-wrap"><p class="eyebrow">A DIFFERENT KIND OF APP</p><h2>Less to manage.<br><span>More to live.</span></h2><div class="approach-grid"><article><span class="principle-number">01</span><h3>Your phone.<br>Your business.</h3><p>Your journal, health records and finances belong to you. These apps keep their records on your iPhone, without an account or a cloud server.</p></article><article><span class="principle-number">02</span><h3>A purchase.<br>Not a subscription.</h3><p>No monthly renewal to remember. Each app offers a one-time purchase, with free features or a trial where described on its page.</p></article><article><span class="principle-number">03</span><h3>A clear purpose.<br>A little less friction.</h3><p>Tools for a specific part of your day. Open the app, do what you came to do, and get back to everything else.</p></article></div></div></section><section class="questions section-wrap" id="questions"><div><p class="eyebrow">GOOD TO KNOW</p><h2>A few answers.</h2></div><div class="faq-list">'''
faqs=[('Who makes these apps?','Ihor Romanenko, an independent developer. All 14 apps on this site link to their public Apple App Store listings.'),('Do I need an account?','No. These apps work without creating an account. Their records and projects are stored on your iPhone.'),('Are there any subscriptions?','No. Each app uses a one-time purchase. Free features and trial limits differ by app; see its page and the current App Store listing.'),('Can I use them offline?','Yes. The core tools and local records work offline. Downloading an app, purchasing an unlock, and services such as AirPrint have their own connectivity requirements.'),('Do the health apps measure or diagnose anything?','No. They are personal journals for readings, symptoms or medicines you enter yourself. They do not measure health values, diagnose conditions or replace professional medical advice.'),('Where can I get help?','Open an app’s App Store listing and follow its App Support link for the support details published for that app.')]
for q,a in faqs:out+=f'<details><summary>{q}<span aria-hidden="true">+</span></summary><p>{a}</p></details>'
out+='</div></section><section class="closing"><p class="eyebrow">A LITTLE SIMPLER, EVERY DAY</p><h2>Make room for<br>the little things.</h2><a class="button" href="#apps">Explore all 14 apps <span aria-hidden="true">↑</span></a></section></main>'+footer()
(ROOT/'index.html').write_text(out)
# Individual product pages: all essential facts are present in server-served HTML.
for a in apps:
 slug,name,cat,title,desc,color,use=meta(a);path=ROOT/slug;path.mkdir(exist_ok=True)
 description=a['description'];blocks=description.split('\n\n');faq=[('Does '+name+' require a subscription?','No. '+next((b for b in blocks if 'SIMPLE PRIC' in b or 'SIMPLE PRICE' in b or 'HONEST PRICING' in b or 'ONE PRICE' in b or 'ONE PAYMENT' in b), 'It uses a one-time purchase. See the App Store for current pricing.').split('\n',1)[-1]),('Where is my data stored?','Records and projects stay on your iPhone. No account or cloud server is required. Check the app’s backup and export options before changing devices or deleting it.'),('What iPhone software does it need?',f'The current listing requires iOS {a["minimumOsVersion"]} or later. Check the App Store for the latest compatibility and availability.')]
 schema={'@context':'https://schema.org','@type':'SoftwareApplication','name':a['trackName'],'applicationCategory':a['primaryGenreName'],'operatingSystem':f'iOS {a["minimumOsVersion"]} or later','url':BASE+slug+'/','downloadUrl':store(a),'image':BASE+icon(a),'description':desc,'author':{'@type':'Person','name':'Ihor Romanenko','url':BASE},'softwareVersion':a['version'],'offers':{'@type':'Offer','price':a['price'],'priceCurrency':a['currency'],'url':store(a)}}
 out=head(a['trackName']+' — Ihor Romanenko',desc,slug+'/', '../',schema,icon(a))+nav('../')
 out+=f'''<div class="product-nav"><div><a href="../#apps">All apps</a><span>{name}</span><a class="button small" href="{store(a)}">View in App Store ↗</a></div></div><main id="main"><section class="product-hero section-wrap"><p class="eyebrow">{cat.upper()} · FOR IPHONE</p><img class="product-icon" src="{icon(a,'../')}" alt="{name} icon" width="80" height="80"><p class="product-name">{name}</p><h1>{title.replace(chr(10),'<br>')}</h1><p class="hero-description">{desc}</p><a class="button" href="{store(a)}">View in App Store <span aria-hidden="true">↗</span></a><p class="purchase-note">No subscription · {'One-time purchase' if a['price'] else 'Free download · One-time unlock'}</p></section><section class="product-gallery" style="--tint:{color}" aria-label="{name} screenshots">'''
 for n in range(1,min(3,len(a['screenshotUrls']))+1):out+=f'<img src="{shot(a,n,"../")}" alt="{name} — App Store screenshot {n}" width="222" height="480" loading="lazy">'
 out+=f'</section><section class="product-story section-wrap"><div class="story-intro"><p class="eyebrow">MADE FOR REAL LIFE</p><h2>{use}.</h2><p>From the developer’s App Store description.</p></div><div class="story-body">'
 for b in blocks:
  lines=b.split('\n');first=lines[0]
  if len(lines)>1 and first.upper()==first and re.search('[A-Z]',first):
   out+='<section><h3>'+esc(first.capitalize())+'</h3>';lines=lines[1:]
   if all(l.startswith('•') for l in lines):out+='<ul>'+''.join('<li>'+esc(l.lstrip('• '))+'</li>' for l in lines)+'</ul>'
   else:out+='<p>'+'<br>'.join(esc(l) for l in lines)+'</p>'
   out+='</section>'
  else:out+='<p>'+esc(b).replace('\n','<br>')+'</p>'
 out+='</div></section><section class="questions section-wrap"><div><p class="eyebrow">GOOD TO KNOW</p><h2>Before you begin.</h2></div><div class="faq-list">'
 for q,answer in faq:out+=f'<details><summary>{esc(q)}<span aria-hidden="true">+</span></summary><p>{esc(answer)}</p></details>'
 out+=f'''</div></section><section class="product-facts section-wrap"><h2>App details.</h2><dl><div><dt>Developer</dt><dd>Ihor Romanenko</dd></div><div><dt>Category</dt><dd>{a['primaryGenreName']}</dd></div><div><dt>Version</dt><dd>{a['version']}</dd></div><div><dt>Compatibility</dt><dd>iOS {a['minimumOsVersion']}+</dd></div><div><dt>Languages in the listing</dt><dd>{len(a['languageCodesISO2A'] or [])}</dd></div><div><dt>App Store ID</dt><dd>{a['trackId']}</dd></div></dl><p class="fineprint">Details checked against the US App Store on October 26, 2026. Prices, supported devices and availability can change. The App Store listing is the current source.</p></section><section class="related section-wrap"><div class="section-heading"><h2>There’s more to explore.</h2><a class="text-link" href="../#apps">All apps ↗</a></div><div class="related-grid">'''
 related=[byid[id] for id in order if id!=a['trackId'] and meta(byid[id])[2]==cat][:3]
 if len(related)<2:related+=[byid[id] for id in order if meta(byid[id])[2]!=cat][:2-len(related)]
 for r in related:out+=f'<a href="../{meta(r)[0]}/"><img src="{icon(r,"../")}" alt="" width="64" height="64" loading="lazy"><h3>{meta(r)[1]}</h3><p>{meta(r)[4]}</p><span class="text-link">Explore ↗</span></a>'
 out+=f'</div></section><section class="closing"><p class="eyebrow">{name.upper()}</p><h2>{title.replace(chr(10),"<br>")}</h2><a class="button" href="{store(a)}">View in App Store ↗</a></section></main>'+footer('../')
 (path/'index.html').write_text(out)
urls=[BASE]+[BASE+copy[id][0]+'/' for id in order]
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+u+'</loc></url>' for u in urls)+'</urlset>')
(ROOT/'.nojekyll').touch()
(ROOT/'favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="18" fill="#1d1d1f"/><text x="32" y="44" text-anchor="middle" font-family="Arial" font-size="40" fill="white" font-weight="700">ir</text></svg>')
print('Built homepage, 14 app pages, metadata and sitemap.')
